-- v10 increment: merge v9 research measurements into v8 SQLite
-- Source: GitHub v9 CSV files, Minecraft Java 1.21.11.
-- Prerequisite: data/MC_Furniture_Style_Stage1_Research_v8.sqlite
-- Does NOT claim official Minecraft client.jar or in-game verification.
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS special_model_layers_v9 (
 model_id TEXT NOT NULL, layer TEXT NOT NULL, cuboids INTEGER NOT NULL,
 flat_elements INTEGER NOT NULL, hierarchy_parts INTEGER NOT NULL,
 tex_width INTEGER NOT NULL, tex_height INTEGER NOT NULL,
 render_type TEXT, part_names TEXT, distinct_cube_sizes TEXT,
 transform_ops INTEGER NOT NULL,
 source_repo_git_blob_sha1 TEXT NOT NULL, source_path TEXT NOT NULL,
 source_csv_git_blob_sha1 TEXT NOT NULL,
 version TEXT NOT NULL DEFAULT '1.21.11',
 PRIMARY KEY(model_id,layer)
);
CREATE TABLE IF NOT EXISTS special_animation_clips_v9 (
 model_id TEXT NOT NULL, clip TEXT NOT NULL, length_seconds REAL NOT NULL,
 loop INTEGER NOT NULL, affected_bones TEXT, channels TEXT,
 sampled_keyframes INTEGER NOT NULL,
 source_repo_git_blob_sha1 TEXT NOT NULL, source_path TEXT NOT NULL,
 source_csv_git_blob_sha1 TEXT NOT NULL,
 version TEXT NOT NULL DEFAULT '1.21.11',
 PRIMARY KEY(model_id,clip)
);
CREATE TABLE IF NOT EXISTS validation_audit_v10 (
 check_id TEXT PRIMARY KEY, scope TEXT NOT NULL, evidence TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('verified','pending','partial')),
 note TEXT NOT NULL
);
